"""Step 7: reports/RESULTS_SUMMARY.md from results/*.csv|json (programmatic; no typed numbers)."""
import json, pandas as pd
from common import *
A = pd.read_csv(RES / "table_pooled_cv.csv"); X = pd.read_csv(RES / "table_cross_dataset.csv"); B = pd.read_csv(RES / "table_best_by_dataset.csv", index_col=0); R = json.load(open(RES / "reference_numbers.json"))
c = lambda d, cols: d[cols].round(2).to_markdown(index=False)
L = ["# Model results (subject-wise validation, rater-1 labels)\n",
     "Generated by `pipeline/07_results_summary.py` from `results/table_*.csv`. **Preliminary:** see caveats at the end.\n",
     "## Pooled subject-wise 5-fold CV, 3 repeats (top 12 of %d configurations)\n" % len(A), c(A.head(12), ["model", "fset", "target", "MAE", "MAE_rep_sd", "SD", "MedAE", "ME", "r"]),
     "\nfset: `sheikh465` = Sheikh et al. 2022 features, `rules` = own rule-based B estimates + RR, `fusion` = both. target: `RB` = B after R-peak, `dRC` = B relative to C-point.\n",
     "## Best configuration by dataset\n", B.round(2).reset_index().rename(columns={"index": "dataset"}).to_markdown(index=False),
     "\n## Reference numbers (best configuration)\n"] + [f"- {k}: {v:.2f} ms" for k, v in R.items()] + ["\n## Cross-dataset transfer (top 5 per direction, selected on the TEST dataset)\n"]
for d, g in X.groupby("direction"): L += [f"**{d}**\n", c(g.head(5), ["model", "fset", "target", "MAE", "SD", "ME", "r"]), ""]
L += ["## Caveats\n", "- Abel et al. (2026) report MAE 8.13 ms with PEPbench's 12 algorithms on 11,239 cycles; this work uses 11,903 cycles and 10 own re-implemented rules, so the numbers are **not directly comparable** until Abel's design is re-run on the identical cohort and folds.",
      "- Sheikh's AdaBoost was tuned on a 4-configuration subset of his grid and his feature definitions were re-implemented from the paper (assumptions marked in `pipeline/03_sheikh_features.py`).",
      "- Cross-dataset rows are the best of many configurations ranked on the test dataset, i.e. optimistic; a train-only selection is still to be done."]
(ROOT / "reports" / "RESULTS_SUMMARY.md").write_text("\n".join(L)); print("ok")
